create or replace function private.aios_validate_invocation_registry() returns trigger language plpgsql security definer set search_path = '' as $$ declare t public.aios_tools; v_hash text; begin if tg_op='UPDATE' then if new.organization_id is distinct from old.organization_id or new.agent_id is distinct from old.agent_id or new.task_id is distinct from old.task_id or new.tool_key is distinct from old.tool_key or new.tool_name is distinct from old.tool_name or new.authorization_version is distinct from old.authorization_version or new.approval_id is distinct from old.approval_id or new.arguments is distinct from old.arguments then if old.status not in ('requested','evaluating') then raise exception 'invocation authorization context is immutable after evaluation begins' using errcode='40001'; end if; end if; end if; select * into t from public.aios_tools where tool_key=coalesce(new.tool_key,new.tool_name); if t.id is null then raise exception 'tool is not registered' using errcode='22023'; end if; if not t.is_enabled or t.status<>'active' then raise exception 'tool is disabled or inactive' using errcode='42501'; end if; if new.tool_key is distinct from t.tool_key or new.tool_name is distinct from t.tool_key then raise exception 'tool identity does not match canonical registry' using errcode='22023'; end if; if not extensions.jsonb_matches_schema(t.input_schema::json,new.arguments) then raise exception 'tool arguments do not match registry input schema' using errcode='22023'; end if; v_hash=encode(extensions.digest(convert_to(new.arguments::text,'UTF8'),'sha256'),'hex'); if tg_op='INSERT' or (new.arguments is distinct from old.arguments and old.status in ('requested','evaluating')) then new.arguments_hash=v_hash; end if; if tg_op='UPDATE' and old.status in ('approved','executing') and new.approval_id is null and t.requires_approval then raise exception 'approval binding cannot be removed from approved execution' using errcode='42501'; end if; return new; end $$;

create or replace function private.aios_validate_approval_integrity() returns trigger language plpgsql security definer set search_path = '' as $$ declare ag public.aios_agents; tk public.aios_tasks; inv public.aios_tool_invocations; begin if new.invocation_id is not null then select * into inv from public.aios_tool_invocations where id=new.invocation_id; if inv.id is null or inv.organization_id<>new.organization_id then raise exception 'approval invocation organization mismatch' using errcode='23514'; end if; if new.agent_id is not null and inv.agent_id is distinct from new.agent_id then raise exception 'approval agent mismatch' using errcode='23514'; end if; if new.task_id is not null and inv.task_id is distinct from new.task_id then raise exception 'approval task mismatch' using errcode='23514'; end if; if new.tool_key is not null and new.tool_key is distinct from inv.tool_key then raise exception 'approval tool mismatch' using errcode='23514'; end if; if new.arguments_hash is not null and new.arguments_hash is distinct from inv.arguments_hash then raise exception 'approval argument hash mismatch' using errcode='23514'; end if; if new.approval_version is not null and inv.authorization_version is not null and new.approval_version is distinct from inv.authorization_version then raise exception 'approval authorization version mismatch' using errcode='23514'; end if; end if; if new.agent_id is not null then select * into ag from public.aios_agents where id=new.agent_id; if ag.id is null or ag.organization_id<>new.organization_id then raise exception 'approval agent organization mismatch' using errcode='23514'; end if; end if; if new.task_id is not null then select * into tk from public.aios_tasks where id=new.task_id; if tk.id is null or tk.organization_id<>new.organization_id then raise exception 'approval task organization mismatch' using errcode='23514'; end if; end if; return new; end $$;
